export function resourceMeta(resource: Resource): ResourceMeta {
  if (resourceMap[resource] !== undefined) {
    return resourceMap[resource];
  } else {
    console.error('Resource not found in resourceMap:', resource);
    return {} as ResourceMeta;
  }
}

export const DomainRouteParam = 'tenantID';

/**
 * The tenant segment as the router matches it: the route every tenant-scoped page lives
 * under, mirroring the API's, with the parameter the tenant guard reads the tenant from.
 */
export const DomainRoutePath = 'tenants/:tenantID';

